#include "stdlib/blas/ext/base/ndarray/ctril.h"
#include "stdlib/ndarray/ctor.h"
#include "stdlib/ndarray/dtypes.h"
#include "stdlib/ndarray/index_modes.h"
#include "stdlib/ndarray/orders.h"
#include "stdlib/ndarray/base/bytes_per_element.h"
#include "stdlib/complex/float32/ctor.h"
#include "stdlib/complex/float32/real.h"
#include "stdlib/complex/float32/imag.h"
#include <stdint.h>
#include <stdlib.h>
#include <stdio.h>

int main( void ) {
	// Create data buffers:
	const stdlib_complex64_t dataA[] = {
		stdlib_complex64( 1.0f, 1.0f ), stdlib_complex64( 2.0f, 2.0f ),
		stdlib_complex64( 3.0f, 3.0f ), stdlib_complex64( 4.0f, 4.0f )
	};
	stdlib_complex64_t dataB[] = {
		stdlib_complex64( 0.0f, 0.0f ), stdlib_complex64( 0.0f, 0.0f ),
		stdlib_complex64( 0.0f, 0.0f ), stdlib_complex64( 0.0f, 0.0f )
	};
	int32_t dataK[] = { 0 };

	// Specify the number of matrix dimensions:
	const int64_t ndims = 2;

	// Specify the matrix shape:
	int64_t shape[] = { 2, 2 };

	// Specify the array strides (in bytes):
	int64_t strides[] = {
		2 * STDLIB_NDARRAY_COMPLEX64_BYTES_PER_ELEMENT,
		STDLIB_NDARRAY_COMPLEX64_BYTES_PER_ELEMENT
	};
	int64_t kstrides[] = { 0 };

	// Specify the byte offset:
	const int64_t offset = 0;

	// Specify the array order:
	const enum STDLIB_NDARRAY_ORDER order = STDLIB_NDARRAY_ROW_MAJOR;

	// Specify the index mode:
	const enum STDLIB_NDARRAY_INDEX_MODE imode = STDLIB_NDARRAY_INDEX_ERROR;

	// Specify the subscript index modes:
	int8_t submodes[] = { STDLIB_NDARRAY_INDEX_ERROR };
	const int64_t nsubmodes = 1;

	// Create ndarrays:
	// cppcheck-suppress invalidPointerCast
	struct ndarray *A = stdlib_ndarray_allocate( STDLIB_NDARRAY_COMPLEX64, (uint8_t *)dataA, ndims, shape, strides, offset, order, imode, nsubmodes, submodes );

	// cppcheck-suppress invalidPointerCast
	struct ndarray *B = stdlib_ndarray_allocate( STDLIB_NDARRAY_COMPLEX64, (uint8_t *)dataB, ndims, shape, strides, offset, order, imode, nsubmodes, submodes );

	// cppcheck-suppress invalidPointerCast
	struct ndarray *k = stdlib_ndarray_allocate( STDLIB_NDARRAY_INT32, (uint8_t *)dataK, 0, NULL, kstrides, offset, order, imode, nsubmodes, submodes );
	if ( A == NULL || B == NULL || k == NULL ) {
		fprintf( stderr, "Error allocating memory.\n" );
		exit( 1 );
	}

	// Define a list of ndarrays:
	const struct ndarray *arrays[] = { A, B, k };

	// Perform computation:
	stdlib_blas_ext_ctril( arrays );

	// Print the result:
	for ( int i = 0; i < 4; i++ ) {
		printf( "dataB[ %i ] = (%f, %f)\n", i, stdlib_complex64_real( dataB[ i ] ), stdlib_complex64_imag( dataB[ i ] ) );
	}

	// Free allocated memory:
	stdlib_ndarray_free( A );
	stdlib_ndarray_free( B );
	stdlib_ndarray_free( k );
}
